-- ============================================================================
-- SC2: Procurement, Tendering & Contracting joins the catalogue, the SECOND
-- course of the Supply Chain module. AN ENGINE COURSE: there is no Suite app;
-- the practicals run in the course's own calculator panels.
--
-- Catalogue row (module 'supply_chain'; path_order 71; prereq_slug
-- NULL, the lead's decision; school left at its default) plus the three
-- capstones and their eighteen graded fields, generated by
-- tools/course-waves/procurement/gen_course.py from the ENGINE'S OWN RUN
-- (sc2_capstone.mjs through the vendored engines/supplychain/tender.js), which
-- it refuses to write unless fields.json carries exactly that run's values
-- and the tolerance gradedTolerance.js derives. Deep seeds are three separate
-- migrations; the go-live is a fifth and is HELD until a NextGen production
-- upload carries the route /dashboard/apps/procurement.
--
-- WHAT IS GRADED. ONITSHA (Associate) grades a technical percentage, a
-- corrected price, an omission at the average, an evaluated cost, a commercial
-- score and the top combined score; UMUAHIA (Professional) grades a
-- life-cycle cost, an evaluated cost, the relative ALB limit, an overall
-- Nigerian content and the s.14 lead under both readings; OKIGWE (Expert)
-- grades the day-rate mean cost, the reimbursable P90 cost (the LOW cost),
-- the company's part of the overrun, the should-cost estimate, the operator's
-- share and the award's ratio to the estimate. Every value is a return value
-- of the engine, and the data it was run on is in the case file the prompt
-- names.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('procurement', 'Procurement, Tendering & Contracting', 'supply_chain', 71, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'procurement', 'beginner', 'associate',
  'ONITSHA, 6 well services bids in two envelopes',
  'Two envelopes, by hand',
  'ONITSHA is a synthetic two-envelope tender, EK-11/WS/2027-19 (synthetic): Coiled tubing scale cleanout with nitrogen lift on Ekene-2 and Ekene-6, with 6 bids, ON1 to ON6. One case file comes with this capstone. onitsha_case.json carries the criteria (id, weight and maxScore), and each bid''s receipt time, mandatory requirements, scores, priced bill lines (quantity, unit rate, quoted amount, and a decimalMisplaced flag where the evaluator recorded one), discount, priced deviations, omitted items and completion weeks. The settings: the pass mark 65; the arithmetic tolerance at the engine default; an omitted item priced at the average of the corrected amounts the other responsive bids quote; completion beyond minWeeks 6 adds ratePerWeek 0.0035 of the corrected price less the discount a week, no credit is given for earlier completion and beyond maxWeeks 10 a bid is rejected; the award is combined at technical weight 0.65, with the lowest-ratio commercial score and the relative technical score; ties at twelve significant digits go to the lower evaluated cost, then the earlier receipt, then the bidder id. Report six values: ON3''s technical percentage; ON2''s corrected price after arithmetic correction; the amount added to ON3 for the item it omits; ON1''s evaluated cost; ON2''s commercial score; and the combined score of the most advantageous bid. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','onitsha_on3_technical_percent', 'label','ON3''s technical percentage', 'unit','percent', 'expected',80.80000000000001, 'tol',5e-07),
    jsonb_build_object('key','onitsha_on2_corrected_price', 'label','ON2''s corrected price', 'unit','money', 'expected',744649.25, 'tol',5e-07),
    jsonb_build_object('key','onitsha_on3_omission_amount', 'label','The amount added for ON3''s omitted item', 'unit','money', 'expected',29783.333333333332, 'tol',5e-07),
    jsonb_build_object('key','onitsha_on1_evaluated_cost', 'label','ON1''s evaluated cost', 'unit','money', 'expected',763703.75, 'tol',5e-07),
    jsonb_build_object('key','onitsha_on2_commercial_score', 'label','ON2''s commercial score', 'unit','points out of 100', 'expected',97.20548915012131, 'tol',5e-07),
    jsonb_build_object('key','onitsha_top_combined_score', 'label','The combined score of the most advantageous bid', 'unit','points out of 100', 'expected',97.93364798993775, 'tol',5e-07)
  )
),
(
  'procurement', 'intermediate', 'professional',
  'UMUAHIA, 6 materials bids, a life cycle and the content Act',
  'The lowest evaluated cost and the content Act',
  'UMUAHIA is a synthetic materials tender, EK-11/MS/2027-23 (synthetic): Casing, gate valves, cement, baryte and inspection for two Ekene infill wells, with 6 bids, UM1 to UM6. One case file comes with this capstone. umuahia_case.json carries the criteria, each bid''s receipt time, mandatory requirements, scores, bill lines, omitted items, delivery weeks, annual valve maintenance costs (years 1 to 6), residual value where one is stated, and Nigerian content by item, and the content items with the line of the 2010 Schedule each falls under. The settings: the pass mark 62; an omitted item priced at the average of the other responsive bids; delivery beyond minWeeks 8 adds ratePerWeek 0.003 a week, beyond maxWeeks 13 rejected; the life cycle 6 years at a discountRate of 0.08, end-of-year discounting, the residual value credited in the last year; the award is the lowest evaluated cost; ties at twelve significant digits go to the lower evaluated cost, then the earlier receipt, then the bidder id. Each bid''s overall Nigerian content weights its items by its own quoted amount for each item, its spend on the item. The abnormally low bid test runs on the evaluated costs of the substantially responsive bids. Section 14 of the Act is read with its group as the bids within 1 percent of the lowest evaluated cost and the closest competitor as the next-highest content in the group. Report six values: UM2''s life-cycle cost; UM4''s evaluated cost; the limit of the abnormally low bid test (the mean of the responsive bids'' evaluated costs less one population standard deviation); UM3''s overall Nigerian content; the s.14 lead of the highest content in the group over its closest competitor read as percentage points; and the same lead read as a percent of the closest competitor''s content. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','umuahia_um2_life_cycle_cost', 'label','UM2''s life-cycle cost', 'unit','money', 'expected',20530.457489562454, 'tol',5e-07),
    jsonb_build_object('key','umuahia_um4_evaluated_cost', 'label','UM4''s evaluated cost', 'unit','money', 'expected',611300.5094501633, 'tol',5e-07),
    jsonb_build_object('key','umuahia_alb_limit', 'label','The relative ALB limit, the mean less one population standard deviation', 'unit','money', 'expected',611951.112477194, 'tol',5e-07),
    jsonb_build_object('key','umuahia_um3_overall_content', 'label','UM3''s overall Nigerian content', 'unit','percent', 'expected',87.04149696003778, 'tol',5e-07),
    jsonb_build_object('key','umuahia_s14_lead_points', 'label','The s.14 lead, read as percentage points', 'unit','percentage points', 'expected',3.8134829361852667, 'tol',5e-07),
    jsonb_build_object('key','umuahia_s14_lead_relative', 'label','The s.14 lead, read as percent of the runner-up''s content', 'unit','percent', 'expected',6.45408598407401, 'tol',5e-07)
  )
),
(
  'procurement', 'advanced', 'expert',
  'OKIGWE, one workover under three contract types, its should-cost and its tender',
  'Contracts, should-cost and the whole tender',
  'OKIGWE is a synthetic job: Fishing and recompletion workover on Ekene-4 (synthetic). One case file comes with this capstone. okigwe_case.json carries the activity programme, the company''s cost items and its partners with their working interests, and a tender for the job: its criteria and 5 bids, OK1 to OK5. The contract settings: the NPT fraction triangular with min 0.04, mode 0.12 and max 0.5 (days are the programme''s productive days times one plus the NPT fraction); the contractor''s daily cost triangular with min 31000, mode 34500 and max 46000; the fixed cost 95000; the lump sum 640000; the day rate 41500 a day plus a mobilisation fee of 120000; the reimbursable contract at cost plus 0.1 of cost; the plan at the modes; 4000 iterations on seed 70611. The should-cost settings: the NPT fraction 0.12, contingency 0.12 of the base, the band from 0.8 to 1.25. The tender settings: the pass mark 60; an omitted item priced at the average; completion beyond minWeeks 3 adds ratePerWeek 0.006 a week, beyond maxWeeks 6 rejected; the award is combined at technical weight 0.75, with the lowest-ratio commercial score and the relative technical score; ties at twelve significant digits go to the lower evaluated cost, then the earlier receipt, then the bidder id. Report six values: the day rate''s mean company cost; the reimbursable contract''s P90 company cost, where P90 means a 90 percent probability the cost meets or exceeds the value, so it is the LOW cost; what the company pays of the expected overrun under the day rate; the should-cost estimate; the operator''s share of it; and the ratio of the awarded bid''s evaluated cost to the estimate. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','okigwe_dayrate_mean_cost', 'label','The day rate''s mean company cost', 'unit','money', 'expected',485297.525439615, 'tol',5e-07),
    jsonb_build_object('key','okigwe_reimbursable_p90_cost', 'label','The reimbursable contract''s P90 company cost, the LOW cost', 'unit','money', 'expected',412328.0252625307, 'tol',5e-07),
    jsonb_build_object('key','okigwe_dayrate_company_pays', 'label','What the company pays of the overrun under the day rate', 'unit','money', 'expected',29822.041700703197, 'tol',5e-07),
    jsonb_build_object('key','okigwe_should_cost_estimate', 'label','The should-cost estimate', 'unit','money', 'expected',629894.997925926, 'tol',5e-07),
    jsonb_build_object('key','okigwe_operator_amount', 'label','The operator''s share of the estimate', 'unit','money', 'expected',267705.37411851855, 'tol',5e-07),
    jsonb_build_object('key','okigwe_award_ratio', 'label','The awarded bid''s evaluated cost over the estimate', 'unit','ratio', 'expected',1.2848642968509094, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
